class Solution:
    def lengthOfLongestSubstring(self, s: str) -> int:
        #first find every possible substring from string
        substrings = []
        for i in range(len(s)):
            for j in range(i, len(s)):
                substrings.append(s[i:j + 1])

        #Now loop through all, store longest length of a substring without duplicates in it
        longest = 0

        for string in substrings:
            seen = []
            for char in string:
                if char in seen:
                    seen.clear() #clear for next string
                    break #don't do nything with this string and move on to next
                else:
                    seen.append(char)
                    longest = max(longest, len(seen))
        return longest

def main():
    solution = Solution()
    print(solution.lengthOfLongestSubstring("abcabcbb"))
    print(solution.lengthOfLongestSubstring("bbbbb"))
    print(solution.lengthOfLongestSubstring("pwwkew"))
